const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // FAO GAUL: Global Administrative Unit Layers 2015, Countries
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const states = ee.FeatureCollection('FAO/GAUL/2015/level1');

  const sriLanka = countries.filter(ee.Filter.eq('ADM0_NAME', 'Sri Lanka')).geometry();
  // Kerala is a state (level 1) in India
  const kerala = states.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.eq('ADM1_NAME', 'Kerala')
  )).geometry();

  const startDate = '2018-07-01';
  const endDate = '2018-08-31';

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
                   .filterDate(startDate, endDate);

  const imageCount = chirps.size().getInfo();
  if (imageCount === 0) {
      console.log('No CHIRPS images found for the specified date range.');
      console.log('A: No');
      return;
  }
  console.log(`Image collection size: ${imageCount}`);

  // 3. Processing
  // Calculate total precipitation for the period
  const totalPrecipitation = chirps.select('precipitation').sum();

  // 4. Calculation & Validation
  const scale = 5000; // CHIRPS native resolution is ~5km

  const keralaStats = totalPrecipitation.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: kerala,
      scale: scale,
      maxPixels: 1e9
  });

  const sriLankaStats = totalPrecipitation.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: sriLanka,
      scale: scale,
      maxPixels: 1e9
  });

  // Extract values using await to handle server-side objects
  const keralaResult = await ee.data.computeValue(keralaStats);
  const sriLankaResult = await ee.data.computeValue(sriLankaStats);

  const keralaMean = keralaResult['precipitation_mean'];
  const keralaPixels = keralaResult['precipitation_count'];
  const sriLankaMean = sriLankaResult['precipitation_mean'];
  const sriLankaPixels = sriLankaResult['precipitation_count'];

  // C2: Check for valid pixels
  if (keralaPixels === 0 || sriLankaPixels === 0) {
      console.log(`Kerala valid pixels: ${keralaPixels}`);
      console.log(`Sri Lanka valid pixels: ${sriLankaPixels}`);
      console.log('No valid pixels found for one or both regions.');
      console.log('C2');
      return;
  }

  // C3: Check for calculation failures
  if (keralaMean === null || sriLankaMean === null) {
      console.log('Calculation failed, result is null.');
      console.log('C3');
      return;
  }

  // 5. Final Answer
  console.log(`Time Period: ${startDate} to ${endDate}`);
  console.log(`Kerala Avg Total Rainfall (mm): ${keralaMean.toFixed(2)} (${keralaPixels} pixels)`);
  console.log(`Sri Lanka Avg Total Rainfall (mm): ${sriLankaMean.toFixed(2)} (${sriLankaPixels} pixels)`);

  if (keralaMean > sriLankaMean) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log('D');
});
